using System;using System.IO;using System.Reflection;using System.Security.Principal;using System.Security.AccessControl;using System.Security.Cryptography;using System.Linq;
#if !SENTINEL_USB_HID_ADMISSION_PRIVATE_QUALIFICATION
#error Private fixture only.
#endif
namespace SentinelHidAdmission {
using UsbExactBlockState=global::UsbHidAdmissionPolicy;
internal static class UsbHidAdmissionBackendQualification {
 const string Safety=@"USB\VID_0001&PID_0001\SYNTHETIC_INTERNAL",A=@"USB\VID_0001&PID_0002\SYNTHETIC_A",B=@"USB\VID_0001&PID_0003\SYNTHETIC_B";
 static void Check(bool ok){if(!ok)throw new InvalidOperationException("Admission backend qualification refused");}
 static UsbExactBlockState.Snapshot Initial(){return new UsbExactBlockState.Snapshot(1,WindowsIdentity.GetCurrent().User.Value,false,new[]{Safety},new string[0],new string('a',64));}
 static void Fixture(UsbExactBlockState.Snapshot s){Check(s!=null&&s.OwnerSid==WindowsIdentity.GetCurrent().User.Value&&s.ReceiptDigest==new string('a',64)&&s.InternalSafety.SequenceEqual(new[]{Safety})&&s.ExternalApprovals.All(id=>id==A||id==B));}
 static UsbExactBlockState.Request Request(string action,UsbExactBlockState.Snapshot before,string[] approvals,string[] targets){var now=DateTime.UtcNow;return new UsbExactBlockState.Request(action,before,new UsbExactBlockState.Snapshot(before.Generation+1,before.OwnerSid,action=="activate"||action!="deactivate"&&before.Active,before.InternalSafety,approvals,before.ReceiptDigest),targets,Guid.NewGuid().ToString("N"),new string('b',64),now,now.AddMinutes(5));}
 static FileSecurity Security(){var acl=new FileSecurity();acl.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.LocalSystemSid,WellKnownSidType.BuiltinAdministratorsSid})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid,null),FileSystemRights.FullControl,AccessControlType.Allow));return acl;}
 static byte[] Worker(){using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("Sentinel.HidAdmission.Worker")){Check(input!=null&&input.Length>0&&input.Length<=67108864);using(var memory=new MemoryStream()){input.CopyTo(memory);return memory.ToArray();}}}
 static string Install(){SentinelPolicyDirectory.Provision(UsbExactBlockRecoveryTasks.CodeRoot);using(var pin=new UsbExactBlockFileStore(UsbExactBlockRecoveryTasks.CodeRoot)){string manifest=Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,"hid-admission-worker.manifest");byte[] bytes=Worker();string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();string target=Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,UsbExactBlockRecoveryTasks.ImageName(hash));if(File.Exists(manifest)){using(var file=new FileStream(manifest,FileMode.Open,FileAccess.Read,FileShare.Read)){Check(file.Length==107);var existingData=new byte[107];int read=0;while(read<existingData.Length){int count=file.Read(existingData,read,existingData.Length-read);Check(count>0);read+=count;}string text=System.Text.Encoding.ASCII.GetString(existingData);Check(System.Text.RegularExpressions.Regex.IsMatch(text,@"\ASNTHIW01\n"+hash+@"\n[0-9a-f]{32}\n\z"));}return hash;}Check(!File.Exists(target));using(var file=new FileStream(target,FileMode.CreateNew,FileSystemRights.Read|FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,Security())){file.Write(bytes,0,bytes.Length);file.Flush(true);}var info=new FileInfo(target);Check((info.Attributes&FileAttributes.ReparsePoint)==0);using(var file=new FileStream(target,FileMode.Open,FileAccess.Read,FileShare.Read))using(var sha=SHA256.Create())Check(BitConverter.ToString(sha.ComputeHash(file)).Replace("-","").ToLowerInvariant()==hash);byte[] data=System.Text.Encoding.ASCII.GetBytes("SNTHIW01\n"+hash+"\n"+Guid.NewGuid().ToString("N")+"\n");Check(data.Length==107);using(var file=new FileStream(manifest,FileMode.CreateNew,FileSystemRights.Read|FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,Security())){file.Write(data,0,data.Length);file.Flush(true);}return hash;}}
 static void Prepare(UsbExactBlockFileStore store,UsbExactBlockBackend backend,UsbExactBlockState.Request request){store.WritePrepared(request);backend.PrepareIndependentRecovery(request);backend.VerifyIndependentRecovery(request);store.AdvancePending(request.Digest,UsbExactBlockState.Stage.Prepared,UsbExactBlockState.Stage.RecoveryArmed);}
 static void Apply(UsbExactBlockFileStore store,UsbExactBlockBackend backend,UsbExactBlockState.Request request,bool commit){Prepare(store,backend,request);backend.ApplyCandidate(request);store.AdvancePending(request.Digest,UsbExactBlockState.Stage.RecoveryArmed,UsbExactBlockState.Stage.Applied);backend.VerifyPolicy(request.After);store.AdvancePending(request.Digest,UsbExactBlockState.Stage.Applied,UsbExactBlockState.Stage.PolicyVerified);if(commit)store.CommitCandidate(request.Digest,request.Before,request.After);}
 static void Retire(UsbExactBlockFileStore store,UsbExactBlockBackend backend,UsbExactBlockState.Request request){backend.StopProducersAndVerifyQuiescent(request);backend.VerifyPolicy(store.ReadCommitted());backend.RetireIndependentRecovery(request);store.RetirePending(request.Digest);Check(store.ReadPending()==null);}
 static void Commit(UsbExactBlockFileStore store,UsbExactBlockBackend backend,UsbExactBlockState.Request request){Apply(store,backend,request,true);store.AdvancePending(request.Digest,UsbExactBlockState.Stage.PolicyVerified,UsbExactBlockState.Stage.Committed);Retire(store,backend,request);}
 static UsbExactBlockFileStore OpenState(){var clock=System.Diagnostics.Stopwatch.StartNew();bool reported=false;for(;;){try{return new UsbExactBlockFileStore(UsbExactBlockBackend.StateRoot);}catch(IOException error){int code=error.HResult&65535;if((code!=32&&code!=33)||clock.ElapsedMilliseconds>=150000)throw;if(!reported){Console.WriteLine("WAIT existing private recovery writer; lock is not bypassed");reported=true;}System.Threading.Thread.Sleep(250);}}}
 [STAThread]public static int Main(string[] args){if(args.Length!=1||(args[0]!="--private-admission-backend"&&args[0]!="--recover-private-only"))return 2;if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 3;int stage=1;try{
  DuckyWorkerJob.AttachCurrentWorker();SentinelPolicyDirectory.Provision(UsbExactBlockRecoveryTasks.CodeRoot);using(var root=new UsbExactBlockFileStore(UsbExactBlockRecoveryTasks.CodeRoot))SentinelPolicyDirectory.Provision(UsbExactBlockBackend.StateRoot);string hash=Install();UsbHidAdmissionBackendCompiler.InstallPrivateFixture();
  using(var store=OpenState()){
   if(store.ReadCommitted()==null&&store.ReadPending()==null)store.InitializeInactive(Initial());
   using(var backend=new UsbExactBlockBackend(store,hash)){
    Console.WriteLine("CHECK private committed/pending state");var interrupted=store.ReadPending();if(interrupted!=null){Fixture(interrupted.Request.Before);Fixture(interrupted.Request.After);Console.WriteLine("CHECK interrupted phase "+interrupted.Phase);var decision=store.ClaimRecovery(interrupted.Request.Digest);Fixture(decision);Console.WriteLine("CHECK stop private producers");backend.StopProducersAndVerifyQuiescent(interrupted.Request);if(UsbExactBlockState.Same(decision,interrupted.Request.Before)){Console.WriteLine("CHECK restore private before image");backend.RestoreBefore(interrupted.Request);}else Check(UsbExactBlockState.Same(decision,interrupted.Request.After));Console.WriteLine("CHECK verify recovered private image");backend.VerifyPolicy(decision);Console.WriteLine("CHECK retire private recovery");backend.RetireIndependentRecovery(interrupted.Request);store.RetirePending(interrupted.Request.Digest);Console.WriteLine("PASS authenticated interrupted synthetic admission recovery");}
    var initial=store.ReadCommitted();Fixture(initial);backend.VerifyPolicy(initial);if(args[0]=="--recover-private-only"){Check(store.ReadPending()==null);Console.WriteLine("PASS private authenticated recovery only; no activation attempted");return 0;}
    if(initial.Active){var cleanup=Request("deactivate",initial,initial.ExternalApprovals,new string[0]);Commit(store,backend,cleanup);initial=cleanup.After;}
    // Prior qualification approvals are explicit synthetic-only state. Remove
    // them through authenticated admission changes after activation, never reset
    // committed generations or recapture machine policy.
    stage=2;var activate=Request("activate",initial,initial.ExternalApprovals,new string[0]);Commit(store,backend,activate);var current=activate.After;
    foreach(string id in current.ExternalApprovals){var clear=Request("block",current,current.ExternalApprovals.Where(x=>x!=id).ToArray(),new[]{id});Commit(store,backend,clear);current=clear.After;}
    stage=3;var one=Request("allow",current,new[]{A},new[]{A});Commit(store,backend,one);var two=Request("allow",one.After,new[]{A,B},new[]{B});Commit(store,backend,two);var blockA=Request("block",two.After,new[]{B},new[]{A});Commit(store,backend,blockA);Check(store.ReadCommitted().ExternalApprovals.SequenceEqual(new[]{B}));Console.WriteLine("PASS suspended named worker activation, approvals A/B, block A preserves B; synthetic private policy only");
    stage=4;var pending=Request("allow",blockA.After,new[]{A,B},new[]{A});Apply(store,backend,pending,false);backend.DispatchRecoveryForQualification(pending);Check(UsbExactBlockState.Same(store.ReadCommitted(),blockA.After));backend.VerifyPolicy(blockA.After);Retire(store,backend,pending);Console.WriteLine("PASS actual SYSTEM precommit admission rollback preserves previous approvals");
    stage=5;var post=Request("allow",blockA.After,new[]{A,B},new[]{A});Apply(store,backend,post,true);backend.DispatchRecoveryForQualification(post);Check(UsbExactBlockState.Same(store.ReadCommitted(),post.After));backend.VerifyPolicy(post.After);Retire(store,backend,post);Console.WriteLine("PASS actual SYSTEM postcommit admission preservation");
    stage=6;var finish=Request("deactivate",post.After,post.After.ExternalApprovals,new string[0]);Commit(store,backend,finish);backend.VerifyPolicy(finish.After);Check(store.ReadPending()==null&&!store.ReadCommitted().Active);Console.WriteLine("PASS private admission backend; no receipt authenticity, Hello, live DeviceInstall, SetupAPI, physical input or reboot claim");return 0;
   }
  }
 }catch(Exception error){Console.WriteLine("FAIL private admission backend stage "+stage);for(int depth=0;error!=null&&depth<8;depth++,error=error.InnerException){Console.WriteLine("MESSAGE "+error.Message);Console.WriteLine("STACK "+error.StackTrace);Console.WriteLine("CAUSE "+depth+" "+error.GetType().Name+" hresult "+error.HResult.ToString("X8")+" site "+(error.TargetSite==null?"none":error.TargetSite.Name));var native=error as System.ComponentModel.Win32Exception;if(native!=null)Console.WriteLine("WIN32 "+native.NativeErrorCode);}return 1;}}
}
}
